    if (kaynak === '#ckKartTipi') { if (!mt && !bolgeEl.value) bolgeEl.value = 'Yurtiçi'; if (tip === 'Müşteri' && $('#ckCariRolu').value === 'Sadece Tedarikçi') $('#ckCariRolu').value = 'Sadece Müşteri'; if (tip === 'Tedarikçi' && $('#ckCariRolu').value === 'Sadece Müşteri') $('#ckCariRolu').value = 'Sadece Tedarikçi'; if (!mt) $('#ckCariRolu').value = 'Diğer'; }
